#!/usr/bin/env python3
"""Generate one atomic SQL release from incremental migrations 004–006.
Never add the generated deployment bundle to the automatic migrations directory.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
MIGRATIONS = [
    '202611030004_approved_push_registration.sql',
    '202611030005_phase1_access_hardening.sql',
    '202611030006_leave_workflow_notifications.sql',
]


def build(migrations=None) -> str:
    migrations = MIGRATIONS if migrations is None else migrations
    sections = [
        '-- GENERATED by scripts/build_phase1_bundle.py. Do not edit.\n'
        '-- One-time release for the supplied pre-004/005/006 schema snapshot.\n'
        '-- Test in staging and coordinate with the new app build. No data deleted.\n'
        'begin;\n'
        "do $$ begin\n"
        "  if to_regprocedure('public.create_direct_conversation(uuid)') is not null\n"
        "     or exists (select 1 from information_schema.columns where table_schema='public'\n"
        "       and table_name='notifications' and column_name='event_key') then\n"
        "    raise exception 'This release is already or partially installed; use migration history instead of replaying the bundle';\n"
        "  end if;\nend; $$;\n"
    ]
    for name in migrations:
        text = (ROOT / 'supabase/migrations' / name).read_text()
        text = '\n'.join(line for line in text.splitlines() if line.strip().lower() not in {'begin;', 'commit;'})
        sections.append('\n-- SOURCE: ' + name + '\n' + text + '\n')
    sections.append('\ncommit;\n')
    return ''.join(sections)


if __name__ == '__main__':
    target = ROOT / 'supabase/deploy/phase1_release.sql'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(build())
    print(target)
